FUNCTION_BLOCK FB_PortStraddleCarrier_SteeringSway
(*
====================================================================================================
 MODULE      : FB_PortStraddleCarrier_SteeringSway
 PROJECT     : LUMINA AUTONOMOUS CONTAINER TERMINAL AUTOMATION PLATFORM (ACTAP-V7)
 SUBSYSTEM   : 8-WHEEL INDEPENDENT HYDRAULIC STEERING & ACTIVE SPREADER SWAY DAMPING SYSTEM
 DESIGNATION : 4-AXLE HIGH-GANTRY STRADDLE CARRIER (AGV-SC) MECHATRONIC INTEGRATION
 STANDARDS   : IEC 61131-3 3rd Ed., ISO 13849-1 Cat 3 / PL d, IEC 62061 SIL 2, ISO 22915-9 (Port Equip)
 AUTHOR      : Lumina Principal Automation Fellow & Cyber-Physical Systems Chair (75+ Yr Fellow)
 ARCHITECTURE:
   1) TRIPLE MODULAR REDUNDANCY (2oo3) VOTING FOR CRITICAL SENSORS:
      - 3x 3-Axis Chassis IMU Accelerometers for Lateral Sway Acceleration [m/s2]
      - 3x Spreader Dynamic Inclinometers / Optical Laser Target Scanners [deg]
   2) MULTI-AXLE INDEPENDENT ACKERMAN KINEMATICS ENGINE:
      - 8 Steered Wheels: Axle 1 (Front), Axle 2 (Mid-Front), Axle 3 (Mid-Rear), Axle 4 (Rear)
      - Concentric Ackerman Geometry around Instantaneous Center of Rotation (ICR)
      - Crab Steering Mode (Synchronous 8-Wheel translation)
      - Carousel / Zero-Turn Mode (Spot rotation around geometric center)
      - Front-Bogie Transit Highway Mode (Axles 1-2 Steer, Axles 3-4 Locked)
   3) SPREADER DYNAMICS & ACTIVE DAMPING (MODEL PREDICTIVE OBSERVER):
      - Inverted Spherical / Suspended Wire Pendulum Model with Variable Rope Length L(t)
      - Continuous-Discrete Extended Luenberger Observer estimating Sway Angle (x1) and Velocity (x2)
      - State Feedback + Chassis Acceleration Disturbance Feedforward to Spreader Skew Cylinders
   4) HYDRAULIC CLOSED-LOOP SERVO VALVE INTEGRATION:
      - Differential Pressure Feedback Compensation (Square-root Orifice Scaling)
      - Proportional Spool Current Drive with Anti-Stiction Dither & Anti-Cavitation Slew Limiting
====================================================================================================
*)

VAR_INPUT
    (* Master Safety Loops & Subsystem Interlocks *)
    bEnable                     : BOOL;     (* System master run permissive [TRUE = System Active] *)
    bEmergencyStop              : BOOL;     (* Monitored dual-channel hardware E-stop loop healthy [TRUE = OK] *)
    bFaultReset                 : BOOL;     (* Rising-edge manual fault acknowledge and latch reset *)

    (* Vehicle Velocity & Kinematic Demands *)
    rSpeedSetpoint_kmh          : REAL;     (* Carrier commanded transit velocity [km/h] [-32.0 .. +32.0] *)
    rSteerAngleDemand_deg       : REAL;     (* Virtual master steering tiller demand [deg] [-45.0 .. +45.0] *)
    iSteerModeDemand            : INT;      (* 0=Concentric Ackerman, 1=Crab 8-Wheel, 2=Carousel Spin, 3=Front Highway *)

    (* Container Hoist & Spreader Physical State *)
    rContainerPayload_ton       : REAL;     (* Suspended container gross cargo mass [ton] [0.0 .. 65.0] *)
    rHoistCableLength_m         : REAL;     (* Instantaneous wire rope suspension drop length [m] [2.0 .. 22.0] *)

    (* Hydraulic Infrastructure Continuous Monitoring *)
    rHydraulicSupplyPres_bar    : REAL;     (* Main continuous high-pressure supply rail [bar] [0.0 .. 350.0] *)
    rHydraulicReturnPres_bar    : REAL;     (* Main low-pressure hydraulic return rail [bar] [0.0 .. 50.0] *)

    (* 2oo3 Triple Modular Redundancy (TMR): Chassis Lateral Accelerometers [m/s2] *)
    rTMR_IMU_AccX_1_ms2         : REAL;     (* IMU Transducer Channel 1 sway acceleration [m/s2] *)
    rTMR_IMU_AccX_2_ms2         : REAL;     (* IMU Transducer Channel 2 sway acceleration [m/s2] *)
    rTMR_IMU_AccX_3_ms2         : REAL;     (* IMU Transducer Channel 3 sway acceleration [m/s2] *)

    (* 2oo3 Triple Modular Redundancy (TMR): Spreader Optical Sway Inclinometers [deg] *)
    rTMR_SpreaderSway_1_deg     : REAL;     (* Optical Inclinometer Channel 1 sway angle [deg] *)
    rTMR_SpreaderSway_2_deg     : REAL;     (* Optical Inclinometer Channel 2 sway angle [deg] *)
    rTMR_SpreaderSway_3_deg     : REAL;     (* Optical Inclinometer Channel 3 sway angle [deg] *)

    (* 8-Wheel Measured Steering Angle Resolvers / LVDTs [deg] *)
    rWheelAngleFeedback_deg     : ARRAY[1..8] OF REAL; (* Actual measured steering angles 1..8 [deg] *)
    rCylinderDiffPres_bar       : ARRAY[1..8] OF REAL; (* Measured steering cylinder differential pressure [bar] *)
END_VAR

VAR_OUTPUT
    (* Operational Health & Safety Indicators *)
    bSystemReady                : BOOL;     (* Subsystem fully initialized, healthy, and operational *)
    bDegradedModeActive         : BOOL;     (* Subsystem operational under degraded sensor or hydraulic envelope *)
    wStatusWord                 : WORD;     (* Detailed bitwise operational status word *)
    wAlarmWord                  : WORD;     (* Diagnostic and safety trip alarm word *)

    (* 8-Wheel Individual Actuation Targets *)
    rWheelAngleSetpoints_deg    : ARRAY[1..8] OF REAL; (* Commanded steering angle for wheels 1..8 [deg] *)
    rValveSpoolCurrent_mA       : ARRAY[1..8] OF REAL; (* Proportional valve drive currents [-1000.0 .. +1000.0 mA] *)
    rWheelSpeedScaling          : ARRAY[1..8] OF REAL; (* Individual electronic differential velocity ratios [0.0 .. 2.0] *)

    (* Spreader Anti-Sway Actuation Commands *)
    rAntiSwayTrimForce_kN       : REAL;     (* Active sway damping restoration force [kN] *)
    rSkewCylinderDelta_mm       : REAL;     (* Spreader skew cylinder differential displacement setpoint [mm] *)
    rEstimatedSwayVelocity_rads : REAL;     (* Observer estimated sway angular velocity [rad/s] *)
    rVotedLateralAccX_ms2       : REAL;     (* 2oo3 voted and validated lateral acceleration [m/s2] *)
    rVotedSwayAngle_deg         : REAL;     (* 2oo3 voted and validated spreader sway angle [deg] *)
END_VAR

VAR
    (* Sequencer State Machine *)
    iState                      : INT := 0; (* Finite State Machine current state *)
    iLastState                  : INT := 0; (* FSM historical state register *)
    tStateTimer                 : TON;      (* State transition dwell and timeout timer *)
    tFaultTimer                 : TON;      (* Alarm debouncing and fault qualification timer *)
    tHighSwayDwellTimer         : TON;      (* Settling confirmation timer during sway suppression *)

    (* Plant Geometry Constants *)
    rHalfTrackWidth_m           : REAL := 2.450;    (* Centerline to wheel hub lateral offset [m] *)
    rAxleX_m                    : ARRAY[1..8] OF REAL := [
        5.200,  5.200,   (* Axle 1: Front-Left (1), Front-Right (2) *)
        1.733,  1.733,   (* Axle 2: Mid-Front-Left (3), Mid-Front-Right (4) *)
       -1.733, -1.733,   (* Axle 3: Mid-Rear-Left (5), Mid-Rear-Right (6) *)
       -5.200, -5.200    (* Axle 4: Rear-Left (7), Rear-Right (8) *)
    ];
    rWheelY_m                   : ARRAY[1..8] OF REAL := [
        2.450, -2.450,   (* Axle 1 *)
        2.450, -2.450,   (* Axle 2 *)
        2.450, -2.450,   (* Axle 3 *)
        2.450, -2.450    (* Axle 4 *)
    ];

    (* 2oo3 Triple Modular Redundancy (TMR) Voting Architecture *)
    bAccChHealthy               : ARRAY[1..3] OF BOOL := [TRUE, TRUE, TRUE];
    bSwayChHealthy              : ARRAY[1..3] OF BOOL := [TRUE, TRUE, TRUE];
    rTMR_AccTol_ms2             : REAL := 0.350;    (* Discrepancy rejection threshold for accelerometers [m/s2] *)
    rTMR_SwayTol_deg            : REAL := 0.450;    (* Discrepancy rejection threshold for optical angle [deg] *)
    rAccDiff12                  : REAL;
    rAccDiff23                  : REAL;
    rAccDiff31                  : REAL;
    rSwayDiff12                 : REAL;
    rSwayDiff23                 : REAL;
    rSwayDiff31                 : REAL;

    (* Continuous-Discrete Luenberger Observer State Vectors & Matrices *)
    rSwayAngleEst_rad           : REAL := 0.0;      (* State x1: Estimated sway angle [rad] *)
    rSwayRateEst_rads           : REAL := 0.0;      (* State x2: Estimated sway angular rate [rad/s] *)
    rSwayAngleEst_dot           : REAL := 0.0;      (* Time derivative dx1/dt [rad/s] *)
    rSwayRateEst_dot            : REAL := 0.0;      (* Time derivative dx2/dt [rad/s2] *)
    rNaturalFreq_rads           : REAL := 1.0;      (* omega_n = sqrt(g / L) [rad/s] *)
    rDampingRatio_Zeta          : REAL := 0.040;    (* Structural + aerodynamic damping ratio *)
    rObserverGain_L1            : REAL := 4.250;    (* Observer angle innovation gain *)
    rObserverGain_L2            : REAL := 18.50;    (* Observer velocity innovation gain *)
    rCtrlGain_Kp                : REAL := 32.00;    (* State feedback proportional stiffness gain *)
    rCtrlGain_Kd                : REAL := 16.50;    (* State feedback derivative damping gain *)
    rFeedforwardGain_Ka         : REAL := 1.150;    (* Direct acceleration inertia cancellation gain *)

    (* Hydraulic Valve Servo Closed-Loop Controllers (8 Channels) *)
    rValveKp                    : REAL := 45.00;    (* Proportional current gain [mA/deg] *)
    rValveKi                    : REAL := 8.500;    (* Integral reset gain [mA/(deg*s)] *)
    rValveDeadband_deg          : REAL := 0.080;    (* Cylinder mechanical seal deadband [deg] *)
    rValveDitherAmp_mA          : REAL := 30.00;    (* High-frequency anti-stiction dither [mA] *)
    rValveIntAccumulator        : ARRAY[1..8] OF REAL; (* Anti-windup integral memory [deg*s] *)
    rMaxSteerAngle_deg          : REAL := 42.00;    (* Physical steering cylinder stroke mechanical stop [deg] *)

    (* Scratch Variables & Mathematical Intermediates *)
    iWheel                      : INT;              (* Loop iterator for 8 wheels *)
    rDt_s                       : REAL := 0.010;    (* Discrete execution interval [s] (100 Hz cyclic task) *)
    rG_ms2                      : REAL := 9.80665;  (* Standard gravity acceleration [m/s2] *)
    rPi                         : REAL := 3.141592653589793;
    rDegToRad                   : REAL := 0.017453292519943;
    rRadToDeg                   : REAL := 57.29577951308232;

    rTurnRadius_R_m             : REAL;             (* Instantaneous turning center radius from vehicle center [m] *)
    rSanitizedTiller_deg        : REAL;             (* Rate-limited & clamped master steer demand [deg] *)
    rTurnCenterDeltaX           : REAL;             (* Longitudinal relative coordinate to ICR [m] *)
    rTurnCenterDeltaY           : REAL;             (* Lateral relative coordinate to ICR [m] *)
    rNominalCenterDist_m        : REAL;             (* Base geometric radius to outer wheel *)
    rWheelRadiusDist_m          : REAL;             (* Radius from ICR to specific wheel hub [m] *)
    rPositionError_deg          : REAL;             (* Closed-loop steering position error [deg] *)
    rEffectiveError_deg         : REAL;             (* Position error after deadband filtering [deg] *)
    rPressureRatioCorr          : REAL;             (* Flow linearization square-root ratio *)
    rPreSatCurrent_mA           : REAL;             (* Unclamped servo valve driver current [mA] *)
    rTotalSuspendedMass_ton     : REAL;             (* Combined spreader tare + payload mass [ton] *)
    rCableLengthClamped_m       : REAL;             (* Sanitized hoist cable length [m] *)
    rRawTrimDemand_mm           : REAL;             (* Commanded anti-sway trim displacement [mm] *)
    rMaxTrackingError_deg       : REAL;             (* Peak cylinder deviation across all 8 bogies [deg] *)
END_VAR

(*
====================================================================================================
 1. HARDWARE SAFETY SUPERVISION & SENSORY BOUNDARY SANITIZATION
====================================================================================================
*)

(* Master Emergency Stop Trip *)
IF NOT bEmergencyStop THEN
    bSystemReady := FALSE;
    wStatusWord.7 := TRUE;  (* E-Stop asserted *)
    wAlarmWord.0 := TRUE;   (* E-Stop Trip Alarm *)
    iState := 99;           (* Emergency shutdown *)
ELSE
    wStatusWord.7 := FALSE;
END_IF;

(* Hydraulic System Pressure Monitoring *)
IF rHydraulicSupplyPres_bar < 160.0 THEN
    wAlarmWord.1 := TRUE;   (* Hydraulic Supply Under-Pressure Warning *)
    bDegradedModeActive := TRUE;
    IF rHydraulicSupplyPres_bar < 110.0 THEN
        wAlarmWord.8 := TRUE; (* Critical Hydraulic Failure Trip *)
        bSystemReady := FALSE;
        iState := 99;
    END_IF;
ELSE
    wAlarmWord.1 := FALSE;
    wAlarmWord.8 := FALSE;
END_IF;

(* Hoist Cable Suspension Length Bounds Check *)
rCableLengthClamped_m := LIMIT(2.0, rHoistCableLength_m, 22.0);
IF (rHoistCableLength_m < 1.8) OR (rHoistCableLength_m > 22.5) THEN
    wAlarmWord.6 := TRUE;   (* Hoist Rope Measurement Out of Bounds *)
ELSE
    wAlarmWord.6 := FALSE;
END_IF;

(* Payload Mass Bounds Check *)
IF rContainerPayload_ton > 65.0 THEN
    wAlarmWord.5 := TRUE;   (* Structural Overload Alarm *)
ELSE
    wAlarmWord.5 := FALSE;
END_IF;
rTotalSuspendedMass_ton := 9.50 + LIMIT(0.0, rContainerPayload_ton, 65.0);

(*
====================================================================================================
 2. 2oo3 TRIPLE MODULAR REDUNDANCY (TMR) VOTING ENGINES
====================================================================================================
*)

(* 2oo3 Engine A: Chassis Lateral IMU Accelerometers [m/s2] *)
rAccDiff12 := ABS(rTMR_IMU_AccX_1_ms2 - rTMR_IMU_AccX_2_ms2);
rAccDiff23 := ABS(rTMR_IMU_AccX_2_ms2 - rTMR_IMU_AccX_3_ms2);
rAccDiff31 := ABS(rTMR_IMU_AccX_3_ms2 - rTMR_IMU_AccX_1_ms2);

IF (rAccDiff12 <= rTMR_AccTol_ms2) AND (rAccDiff23 <= rTMR_AccTol_ms2) AND (rAccDiff31 <= rTMR_AccTol_ms2) THEN
    (* All 3 channels concordant *)
    rVotedLateralAccX_ms2 := (rTMR_IMU_AccX_1_ms2 + rTMR_IMU_AccX_2_ms2 + rTMR_IMU_AccX_3_ms2) / 3.0;
    bAccChHealthy[1] := TRUE;
    bAccChHealthy[2] := TRUE;
    bAccChHealthy[3] := TRUE;
    wAlarmWord.2 := FALSE;
ELSIF (rAccDiff12 <= rTMR_AccTol_ms2) THEN
    (* Channel 3 divergent *)
    rVotedLateralAccX_ms2 := (rTMR_IMU_AccX_1_ms2 + rTMR_IMU_AccX_2_ms2) * 0.5;
    bAccChHealthy[1] := TRUE;
    bAccChHealthy[2] := TRUE;
    bAccChHealthy[3] := FALSE;
    bDegradedModeActive := TRUE;
ELSIF (rAccDiff23 <= rTMR_AccTol_ms2) THEN
    (* Channel 1 divergent *)
    rVotedLateralAccX_ms2 := (rTMR_IMU_AccX_2_ms2 + rTMR_IMU_AccX_3_ms2) * 0.5;
    bAccChHealthy[1] := FALSE;
    bAccChHealthy[2] := TRUE;
    bAccChHealthy[3] := TRUE;
    bDegradedModeActive := TRUE;
ELSIF (rAccDiff31 <= rTMR_AccTol_ms2) THEN
    (* Channel 2 divergent *)
    rVotedLateralAccX_ms2 := (rTMR_IMU_AccX_1_ms2 + rTMR_IMU_AccX_3_ms2) * 0.5;
    bAccChHealthy[1] := TRUE;
    bAccChHealthy[2] := FALSE;
    bAccChHealthy[3] := TRUE;
    bDegradedModeActive := TRUE;
ELSE
    (* Complete Triple Modular Redundancy Divergence *)
    rVotedLateralAccX_ms2 := 0.0;
    bAccChHealthy[1] := FALSE;
    bAccChHealthy[2] := FALSE;
    bAccChHealthy[3] := FALSE;
    wAlarmWord.2 := TRUE;   (* TMR IMU Failure Alarm *)
    bDegradedModeActive := TRUE;
END_IF;

(* 2oo3 Engine B: Optical Spreader Sway Inclinometers [deg] *)
rSwayDiff12 := ABS(rTMR_SpreaderSway_1_deg - rTMR_SpreaderSway_2_deg);
rSwayDiff23 := ABS(rTMR_SpreaderSway_2_deg - rTMR_SpreaderSway_3_deg);
rSwayDiff31 := ABS(rTMR_SpreaderSway_3_deg - rTMR_SpreaderSway_1_deg);

IF (rSwayDiff12 <= rTMR_SwayTol_deg) AND (rSwayDiff23 <= rTMR_SwayTol_deg) AND (rSwayDiff31 <= rTMR_SwayTol_deg) THEN
    (* All 3 channels concordant *)
    rVotedSwayAngle_deg := (rTMR_SpreaderSway_1_deg + rTMR_SpreaderSway_2_deg + rTMR_SpreaderSway_3_deg) / 3.0;
    bSwayChHealthy[1] := TRUE;
    bSwayChHealthy[2] := TRUE;
    bSwayChHealthy[3] := TRUE;
    wAlarmWord.3 := FALSE;
ELSIF (rSwayDiff12 <= rTMR_SwayTol_deg) THEN
    (* Channel 3 divergent *)
    rVotedSwayAngle_deg := (rTMR_SpreaderSway_1_deg + rTMR_SpreaderSway_2_deg) * 0.5;
    bSwayChHealthy[1] := TRUE;
    bSwayChHealthy[2] := TRUE;
    bSwayChHealthy[3] := FALSE;
    bDegradedModeActive := TRUE;
ELSIF (rSwayDiff23 <= rTMR_SwayTol_deg) THEN
    (* Channel 1 divergent *)
    rVotedSwayAngle_deg := (rTMR_SpreaderSway_2_deg + rTMR_SpreaderSway_3_deg) * 0.5;
    bSwayChHealthy[1] := FALSE;
    bSwayChHealthy[2] := TRUE;
    bSwayChHealthy[3] := TRUE;
    bDegradedModeActive := TRUE;
ELSIF (rSwayDiff31 <= rTMR_SwayTol_deg) THEN
    (* Channel 2 divergent *)
    rVotedSwayAngle_deg := (rTMR_SpreaderSway_1_deg + rTMR_SpreaderSway_3_deg) * 0.5;
    bSwayChHealthy[1] := TRUE;
    bSwayChHealthy[2] := FALSE;
    bSwayChHealthy[3] := TRUE;
    bDegradedModeActive := TRUE;
ELSE
    (* Triple Modular Inclinometer Failure *)
    rVotedSwayAngle_deg := 0.0;
    bSwayChHealthy[1] := FALSE;
    bSwayChHealthy[2] := FALSE;
    bSwayChHealthy[3] := FALSE;
    wAlarmWord.3 := TRUE;   (* TMR Sway Sensor Failure Alarm *)
    bDegradedModeActive := TRUE;
END_IF;

(* Critical Sway Threshold Detection *)
IF ABS(rVotedSwayAngle_deg) > 4.50 THEN
    wAlarmWord.7 := TRUE;   (* Excessive Dangerous Spreader Sway *)
ELSE
    wAlarmWord.7 := FALSE;
END_IF;

(*
====================================================================================================
 3. CONTINUOUS LUENBERGER OBSERVER & SPREADER ACTIVE SWAY SUPPRESSION
====================================================================================================
*)

(* Pendulum Dynamics Model: omega_n = sqrt(g / L) *)
rNaturalFreq_rads := SQRT(rG_ms2 / rCableLengthClamped_m);

(* Luenberger Innovation / Residual: e_y = y_meas - x1_est *)
rSwayAngleEst_dot := rSwayRateEst_rads + rObserverGain_L1 * ((rVotedSwayAngle_deg * rDegToRad) - rSwayAngleEst_rad);

rSwayRateEst_dot  := - (EXPT(rNaturalFreq_rads, 2) * rSwayAngleEst_rad)
                     - (2.0 * rDampingRatio_Zeta * rNaturalFreq_rads * rSwayRateEst_rads)
                     - (rVotedLateralAccX_ms2 / rCableLengthClamped_m)
                     + rObserverGain_L2 * ((rVotedSwayAngle_deg * rDegToRad) - rSwayAngleEst_rad);

(* Numerical Integration (Euler Step, Ts = 0.010 s) *)
rSwayAngleEst_rad := rSwayAngleEst_rad + (rSwayAngleEst_dot * rDt_s);
rSwayRateEst_rads := rSwayRateEst_rads + (rSwayRateEst_dot * rDt_s);
rEstimatedSwayVelocity_rads := rSwayRateEst_rads;

(* State Feedback Control Law with Direct Acceleration Feedforward *)
rRawTrimDemand_mm := (rCtrlGain_Kp * rSwayAngleEst_rad * rRadToDeg * 12.0)
                   + (rCtrlGain_Kd * rSwayRateEst_rads * 85.0)
                   + (rFeedforwardGain_Ka * (rVotedLateralAccX_ms2 / rG_ms2) * 95.0);

(* Clamping Skew Actuator Stroke to Physical Envelope [-150.0 .. +150.0 mm] *)
rSkewCylinderDelta_mm := LIMIT(-150.0, rRawTrimDemand_mm, 150.0);

(* Dynamic Restoration Damping Force Calculation [kN] *)
rAntiSwayTrimForce_kN := (rTotalSuspendedMass_ton * (rG_ms2 * SIN(rSwayAngleEst_rad) + (rCableLengthClamped_m * rSwayRateEst_dot))) / 1000.0;

(*
====================================================================================================
 4. 8-WHEEL MULTI-AXLE INDEPENDENT KINEMATICS ENGINE
====================================================================================================
*)

(* Master Tiller Demand Sanitization *)
rSanitizedTiller_deg := LIMIT(-rMaxSteerAngle_deg, rSteerAngleDemand_deg, rMaxSteerAngle_deg);

CASE iSteerModeDemand OF
    0: (* Concentric Ackerman Kinematics (All 8 Wheels Active) *)
        wStatusWord.8 := TRUE;
        wStatusWord.9 := FALSE;
        wStatusWord.10 := FALSE;

        IF ABS(rSanitizedTiller_deg) < 0.10 THEN
            (* Pure Straight-Line Transit *)
            FOR iWheel := 1 TO 8 DO
                rWheelAngleSetpoints_deg[iWheel] := 0.0;
                rWheelSpeedScaling[iWheel] := 1.0;
            END_FOR;
        ELSE
            (* Calculate Instantaneous Radius to Geometric Center: R = L_pivot / tan(delta) *)
            rTurnRadius_R_m := 5.200 / TAN(rSanitizedTiller_deg * rDegToRad);

            FOR iWheel := 1 TO 8 DO
                rTurnCenterDeltaX := rAxleX_m[iWheel];
                rTurnCenterDeltaY := rTurnRadius_R_m - rWheelY_m[iWheel];

                (* Individual Wheel Steering Angle: delta_i = atan(dx / dy) *)
                rWheelAngleSetpoints_deg[iWheel] := ATAN2(rTurnCenterDeltaX, rTurnCenterDeltaY) * rRadToDeg;

                (* Electronic Differential Speed Scaling proportional to turning arc length *)
                rWheelRadiusDist_m := SQRT(EXPT(rTurnCenterDeltaX, 2) + EXPT(rTurnCenterDeltaY, 2));
                rWheelSpeedScaling[iWheel] := LIMIT(0.20, rWheelRadiusDist_m / ABS(rTurnRadius_R_m), 1.80);
            END_FOR;
        END_IF;

    1: (* Crab Steering Mode (Synchronous 8-Wheel Translation) *)
        wStatusWord.8 := FALSE;
        wStatusWord.9 := TRUE;
        wStatusWord.10 := FALSE;

        FOR iWheel := 1 TO 8 DO
            rWheelAngleSetpoints_deg[iWheel] := rSanitizedTiller_deg;
            rWheelSpeedScaling[iWheel] := 1.0;
        END_FOR;

    2: (* Carousel / Zero-Turn Mode (Spot Spin about Center of Geometry) *)
        wStatusWord.8 := FALSE;
        wStatusWord.9 := FALSE;
        wStatusWord.10 := TRUE;

        rNominalCenterDist_m := SQRT(EXPT(5.200, 2) + EXPT(rHalfTrackWidth_m, 2));
        FOR iWheel := 1 TO 8 DO
            (* Perpendicular vector to radius from center (X_i, Y_i) *)
            rWheelAngleSetpoints_deg[iWheel] := ATAN2(-rAxleX_m[iWheel], rWheelY_m[iWheel]) * rRadToDeg;
            rWheelRadiusDist_m := SQRT(EXPT(rAxleX_m[iWheel], 2) + EXPT(rWheelY_m[iWheel], 2));
            rWheelSpeedScaling[iWheel] := rWheelRadiusDist_m / rNominalCenterDist_m;
        END_FOR;

    3: (* Front-Bogie Transit Highway Mode (Axles 1 & 2 Steer, Axles 3 & 4 Fixed at 0 deg) *)
        wStatusWord.8 := FALSE;
        wStatusWord.9 := FALSE;
        wStatusWord.10 := FALSE;

        IF ABS(rSanitizedTiller_deg) < 0.10 THEN
            FOR iWheel := 1 TO 8 DO
                rWheelAngleSetpoints_deg[iWheel] := 0.0;
                rWheelSpeedScaling[iWheel] := 1.0;
            END_FOR;
        ELSE
            (* Virtual rear pivot located at mean of Axles 3 & 4 (-3.466 m) *)
            rTurnRadius_R_m := (5.200 - (-3.466)) / TAN(rSanitizedTiller_deg * rDegToRad);

            FOR iWheel := 1 TO 4 DO
                rTurnCenterDeltaX := rAxleX_m[iWheel] - (-3.466);
                rTurnCenterDeltaY := rTurnRadius_R_m - rWheelY_m[iWheel];
                rWheelAngleSetpoints_deg[iWheel] := ATAN2(rTurnCenterDeltaX, rTurnCenterDeltaY) * rRadToDeg;
                rWheelSpeedScaling[iWheel] := SQRT(EXPT(rTurnCenterDeltaX, 2) + EXPT(rTurnCenterDeltaY, 2)) / ABS(rTurnRadius_R_m);
            END_FOR;

            (* Lock Rear Bogies (Wheels 5..8) *)
            FOR iWheel := 5 TO 8 DO
                rWheelAngleSetpoints_deg[iWheel] := 0.0;
                rWheelSpeedScaling[iWheel] := 1.0;
            END_FOR;
        END_IF;

    ELSE
        (* Default Safe Fallback: Parallel Alignment *)
        FOR iWheel := 1 TO 8 DO
            rWheelAngleSetpoints_deg[iWheel] := 0.0;
            rWheelSpeedScaling[iWheel] := 1.0;
        END_FOR;
END_CASE;

(*
====================================================================================================
 5. HYDRAULIC CLOSED-LOOP SERVO VALVE CURRENT GENERATION (8 WHEELS)
====================================================================================================
*)

(* Hydraulic Flow Linearization: sqrt(DeltaP_nom / DeltaP_actual) *)
rPressureRatioCorr := SQRT(265.0 / MAX(35.0, (rHydraulicSupplyPres_bar - rHydraulicReturnPres_bar)));
rMaxTrackingError_deg := 0.0;

FOR iWheel := 1 TO 8 DO
    rPositionError_deg := rWheelAngleSetpoints_deg[iWheel] - rWheelAngleFeedback_deg[iWheel];

    (* Track peak tracking error *)
    IF ABS(rPositionError_deg) > rMaxTrackingError_deg THEN
        rMaxTrackingError_deg := ABS(rPositionError_deg);
    END_IF;

    (* Cylinder Mechanical Deadband Filter *)
    IF ABS(rPositionError_deg) <= rValveDeadband_deg THEN
        rEffectiveError_deg := 0.0;
    ELSIF rPositionError_deg > rValveDeadband_deg THEN
        rEffectiveError_deg := rPositionError_deg - rValveDeadband_deg;
    ELSE
        rEffectiveError_deg := rPositionError_deg + rValveDeadband_deg;
    END_IF;

    (* Anti-Windup Integral Error Accumulation *)
    rValveIntAccumulator[iWheel] := LIMIT(-12.0, rValveIntAccumulator[iWheel] + (rEffectiveError_deg * rDt_s), 12.0);

    (* Closed-Loop PI Output Current Calculation *)
    rPreSatCurrent_mA := (rValveKp * rEffectiveError_deg) + (rValveKi * rValveIntAccumulator[iWheel]);

    (* Valve Anti-Stiction Dither Superposition *)
    IF ABS(rEffectiveError_deg) > 0.010 THEN
        IF rEffectiveError_deg > 0.0 THEN
            rPreSatCurrent_mA := rPreSatCurrent_mA + rValveDitherAmp_mA;
        ELSE
            rPreSatCurrent_mA := rPreSatCurrent_mA - rValveDitherAmp_mA;
        END_IF;
    END_IF;

    (* Square-root Pressure Compensation & Electrical Saturation [-1000.0 .. +1000.0 mA] *)
    IF iState = 99 THEN
        rValveSpoolCurrent_mA[iWheel] := 0.0; (* Mechanical centering spring clamp *)
    ELSE
        rValveSpoolCurrent_mA[iWheel] := LIMIT(-1000.0, rPreSatCurrent_mA * rPressureRatioCorr, 1000.0);
    END_IF;
END_FOR;

(* Qualify Cylinder Tracking Fault Alarm *)
IF rMaxTrackingError_deg > 3.80 THEN
    tFaultTimer(IN := TRUE, PT := T#500MS);
    IF tFaultTimer.Q THEN
        wAlarmWord.4 := TRUE; (* Steering Servo Tracking Mismatch Trip *)
    END_IF;
ELSE
    tFaultTimer(IN := FALSE);
    wAlarmWord.4 := FALSE;
END_IF;

(*
====================================================================================================
 6. MULTI-STAGE CYBER-PHYSICAL STATE SEQUENCER (CASE iState OF)
====================================================================================================
*)

CASE iState OF

    0: (* STATE_BOOT_DIAGNOSTICS: Sensor Health Verification & Calibration *)
        bSystemReady := FALSE;
        wStatusWord.0 := FALSE;
        tStateTimer(IN := TRUE, PT := T#1500MS);

        (* Reset accumulators and state registers *)
        FOR iWheel := 1 TO 8 DO
            rValveIntAccumulator[iWheel] := 0.0;
        END_FOR;
        rSwayAngleEst_rad := 0.0;
        rSwayRateEst_rads := 0.0;

        IF tStateTimer.Q AND bEnable AND bEmergencyStop AND (wAlarmWord = 16#0000) THEN
            tStateTimer(IN := FALSE);
            iState := 10;
        END_IF;

    10: (* STATE_HYDRAULIC_PRESSURIZATION: Confirm Rail Pressure Buildup *)
        bSystemReady := FALSE;
        tStateTimer(IN := TRUE, PT := T#2000MS);

        IF (rHydraulicSupplyPres_bar >= 180.0) AND tStateTimer.Q THEN
            tStateTimer(IN := FALSE);
            iState := 20;
        ELSIF tStateTimer.Q AND (rHydraulicSupplyPres_bar < 180.0) THEN
            wAlarmWord.1 := TRUE;
            iState := 99;
        END_IF;

    20: (* STATE_WHEEL_HOMING_ALIGNMENT: Steer All 8 Wheels to Mechanical Center *)
        bSystemReady := FALSE;
        wStatusWord.4 := FALSE;
        tStateTimer(IN := TRUE, PT := T#3000MS);

        (* Force zero degree setpoint during homing *)
        FOR iWheel := 1 TO 8 DO
            rWheelAngleSetpoints_deg[iWheel] := 0.0;
        END_FOR;

        IF (rMaxTrackingError_deg < 0.25) AND tStateTimer.Q THEN
            tStateTimer(IN := FALSE);
            wStatusWord.4 := TRUE; (* Wheels Centered *)
            bSystemReady := TRUE;
            iState := 30;
        END_IF;

    30: (* STATE_NOMINAL_TRANSIT: Full Coordinated Steering & Anti-Sway Active *)
        bSystemReady := TRUE;
        wStatusWord.0 := TRUE;

        (* Interlock check *)
        IF NOT bEnable THEN
            bSystemReady := FALSE;
            iState := 20; (* Return to zero align *)
        ELSIF ABS(rVotedSwayAngle_deg) > 3.20 THEN
            iState := 60; (* Divert to High Sway Suppression *)
        ELSIF bDegradedModeActive THEN
            iState := 80; (* Transition to Degraded Envelope *)
        END_IF;

    60: (* STATE_HIGH_SWAY_RECOVERY: Priority Damping & Transit Velocity Suppression *)
        bSystemReady := TRUE;
        wStatusWord.5 := FALSE;

        (* Suppress ground drive speed during heavy sway to prioritize lateral stability *)
        FOR iWheel := 1 TO 8 DO
            rWheelSpeedScaling[iWheel] := rWheelSpeedScaling[iWheel] * 0.35;
        END_FOR;

        (* Check sway subsidence *)
        IF ABS(rVotedSwayAngle_deg) < 0.40 THEN
            tHighSwayDwellTimer(IN := TRUE, PT := T#2000MS);
            IF tHighSwayDwellTimer.Q THEN
                tHighSwayDwellTimer(IN := FALSE);
                wStatusWord.5 := TRUE; (* Sway Damped *)
                iState := 30;          (* Return to nominal transit *)
            END_IF;
        ELSE
            tHighSwayDwellTimer(IN := FALSE);
        END_IF;

    80: (* STATE_DEGRADED_LIMP_HOME: Operates under single sensor fault or low hydraulic rail *)
        bSystemReady := TRUE;
        bDegradedModeActive := TRUE;
        wStatusWord.6 := TRUE;

        (* Restrict maximum transit velocity to 8 km/h and limit tiller demand *)
        IF (rSpeedSetpoint_kmh > 8.0) OR (rSpeedSetpoint_kmh < -8.0) THEN
            (* Speed violation in degraded mode *)
            wAlarmWord.9 := TRUE;
        ELSE
            wAlarmWord.9 := FALSE;
        END_IF;

        (* If faults cleared and reset pressed, recover to nominal *)
        IF bFaultReset AND (wAlarmWord = 16#0000) AND (rHydraulicSupplyPres_bar >= 210.0) THEN
            bDegradedModeActive := FALSE;
            wStatusWord.6 := FALSE;
            iState := 30;
        END_IF;

    99: (* STATE_EMERGENCY_SHUTDOWN: Hydraulic Spool Nulling & Caliper Lock *)
        bSystemReady := FALSE;
        wStatusWord.0 := FALSE;

        (* De-energize all proportional valves *)
        FOR iWheel := 1 TO 8 DO
            rValveSpoolCurrent_mA[iWheel] := 0.0;
            rWheelSpeedScaling[iWheel] := 0.0;
        END_FOR;
        rAntiSwayTrimForce_kN := 0.0;
        rSkewCylinderDelta_mm := 0.0;

        (* Require physical E-Stop release, reset command, and disable to leave *)
        IF bEmergencyStop AND bFaultReset AND (NOT bEnable) THEN
            wAlarmWord := 16#0000;
            iState := 0;
        END_IF;

END_CASE;

(*
====================================================================================================
 7. BITWISE STATUS AND DIAGNOSTIC WORD COMPILATION
====================================================================================================
*)
wStatusWord.1 := (rHydraulicSupplyPres_bar >= 180.0);
wStatusWord.2 := bAccChHealthy[1] AND bAccChHealthy[2] AND bAccChHealthy[3];
wStatusWord.3 := bSwayChHealthy[1] AND bSwayChHealthy[2] AND bSwayChHealthy[3];
wStatusWord.5 := (ABS(rVotedSwayAngle_deg) <= 0.150);
wStatusWord.6 := bDegradedModeActive;

END_FUNCTION_BLOCK
